select id, full_name, dept_id, hire_date, is_remote, level, row_number() over (partition by date_trunc('WEEK', hire_date), level order by hire_date, id) as row_seq, sum(salary) over (partition by job_title order by salary, id rows between unbounded preceding and current row) as cumulative_salary, rank() over (partition by dept_id order by salary desc) as salary_rank, sum(salary) over (partition by dept_id order by hire_date, id rows between unbounded preceding and current row) as cumulative_salary_2 from employees
